  ('aa500002-cc00-0000-0000-000000000002', 'ca9a0012-0000-0000-0000-000000000012', 'MA', 'a2222222-aaaa-aaaa-aaaa-aaaaaaaaaaaa', 'activity', 'Casablanca Surf Lesson', 'A beginner surf lesson at Ain Diab beach, with wetsuit and board included.', ARRAY['en','fr','ary-Latn'], 10, 2, '{}', 1, 6, 120, 1, 'active', 'https://images.pexels.com/photos/7835701/pexels-photo-7835701.jpeg?auto=compress&cs=tinysrgb&h=650&w=940'),
