  ('aa500004-cc00-0000-0000-000000000004', 'ca9a0012-0000-0000-0000-000000000012', 'MA', 'a2222222-aaaa-aaaa-aaaa-aaaaaaaaaaaa', 'activity', 'Casablanca Jet Ski', 'A 1-hour jet ski ride along the Casablanca coast, with instructor and safety gear.', ARRAY['en','fr','es','ary-Latn'], 16, 2, '{}', 1, 4, 60, 2, 'active', 'https://images.pexels.com/photos/18554039/pexels-photo-18554039.jpeg?auto=compress&cs=tinysrgb&h=650&w=940'),
  ('aa500005-cc00-0000-0000-000000000005', 'ca9a0012-0000-0000-0000-000000000012', 'MA', 'a2222222-aaaa-aaaa-aaaa-aaaaaaaaaaaa', 'guided_experience', 'Casablanca Twin Center Rooftop Tour', 'A guided tour to the rooftop of the Casablanca Twin Center, with panoramic city views.', ARRAY['en','fr','es','it','ary-Latn'], 10, 1, '{}', 1, 10, 60, 2, 'active', 'https://images.pexels.com/photos/30367293/pexels-photo-30367293.jpeg?auto=compress&cs=tinysrgb&h=650&w=940'),
