  ('aa500007-cc00-0000-0000-000000000007', 'ea9a0014-0000-0000-0000-000000000014', 'MA', 'a2222222-aaaa-aaaa-aaaa-aaaaaaaaaaaa', 'guided_experience', 'Casablanca Nightlife & Bar Walk', 'A guided evening walk through Casablanca''s best bars and lounges, from Gueliz to the Corniche.', ARRAY['en','fr','es','ary-Latn'], 18, 1, '{}', 2, 10, 180, 2, 'active', 'https://images.pexels.com/photos/30668291/pexels-photo-30668291.jpeg?auto=compress&cs=tinysrgb&h=650&w=940'),
  ('aa500008-cc00-0000-0000-000000000008', 'ca9a0012-0000-0000-0000-000000000012', 'MA', 'a2222222-aaaa-aaaa-aaaa-aaaaaaaaaaaa', 'guided_experience', 'Casablanca Photography Walk', 'A guided photography walk through the art deco district, with tips from a local photographer.', ARRAY['en','fr','es','it','ary-Latn'], 12, 2, '{}', 1, 8, 150, 2, 'active', 'https://images.pexels.com/photos/19280616/pexels-photo-19280616.jpeg?auto=compress&cs=tinysrgb&h=650&w=940'),
  ('aa500009-cc00-0000-0000-000000000009', 'ea9a0014-0000-0000-0000-000000000014', 'MA', 'a2222222-aaaa-aaaa-aaaa-aaaaaaaaaaaa', 'meal', 'Casablanca Couscous Royal Lunch', 'A royal couscous lunch with lamb, seven vegetables and caramelised onions at a traditional restaurant.', ARRAY['en','fr','ary-Latn','ber'], 5, 1, '{}', 1, 10, 90, 2, 'active', 'https://images.pexels.com/photos/36916123/pexels-photo-36916123.jpeg?auto=compress&cs=tinysrgb&h=650&w=940'),
  ('aa50000a-cc00-0000-0000-00000000000a', 'ea9a0014-0000-0000-0000-000000000014', 'MA', 'a2222222-aaaa-aaaa-aaaa-aaaaaaaaaaaa', 'meal', 'Casablanca Rooftop Dinner', 'A Moroccan dinner on a Casablanca rooftop, with tagine, pastilla and mint tea under the stars.', ARRAY['en','fr','es','ary-Latn'], 10, 1, '{}', 2, 12, 120, 3, 'active', 'https://images.pexels.com/photos/36984667/pexels-photo-36984667.jpeg?auto=compress&cs=tinysrgb&h=650&w=940'),
