  ('aa50000c-cc00-0000-0000-00000000000c', 'da9a0013-0000-0000-0000-000000000013', 'MA', 'a2222222-aaaa-aaaa-aaaa-aaaaaaaaaaaa', 'stay', 'Casa Corniche Resort (per night)', 'A seafront resort with pool, spa and private beach access, 10 minutes from the medina.', ARRAY['en','fr','es','it','ru','ary-Arab'], 0, 1, '{}', 1, 4, 1440, 4, 'active', 'https://images.pexels.com/photos/15531178/pexels-photo-15531178.jpeg?auto=compress&cs=tinysrgb&h=650&w=940'),
  ('aa50000d-cc00-0000-0000-00000000000d', 'da9a0013-0000-0000-0000-000000000013', 'MA', 'a2222222-aaaa-aaaa-aaaa-aaaaaaaaaaaa', 'stay', 'Casa Medina Riad (per night)', 'A traditional riad within the old medina walls, with courtyard, rooftop and breakfast.', ARRAY['en','fr','es','ary-Arab','ber'], 0, 1, '{}', 1, 4, 1440, 3, 'active', 'https://images.pexels.com/photos/15531325/pexels-photo-15531325.jpeg?auto=compress&cs=tinysrgb&h=650&w=940'),
  ('aa50000e-cc00-0000-0000-00000000000e', 'ca9a0012-0000-0000-0000-000000000012', 'MA', 'a2222222-aaaa-aaaa-aaaa-aaaaaaaaaaaa', 'workshop', 'Casablanca Cooking Class', 'Learn to cook Moroccan classics — tagine, pastilla, harira — in a professional kitchen.', ARRAY['en','fr','es','ary-Latn','ber'], 12, 1, '{}', 1, 8, 180, 2, 'active', 'https://images.pexels.com/photos/6223144/pexels-photo-6223144.jpeg?auto=compress&cs=tinysrgb&h=650&w=940'),
  ('aa50000f-cc00-0000-0000-00000000000f', 'ca9a0012-0000-0000-0000-000000000012', 'MA', 'a2222222-aaaa-aaaa-aaaa-aaaaaaaaaaaa', 'workshop', 'Casablanca Calligraphy Workshop', 'Learn Arabic calligraphy with a master calligrapher in the Habous district.', ARRAY['en','fr','es','it','ary-Arab'], 10, 1, '{}', 1, 6, 90, 1, 'active', 'https://images.pexels.com/photos/30563520/pexels-photo-30563520.jpeg?auto=compress&cs=tinysrgb&h=650&w=940'),
  ('aa500010-cc00-0000-0000-000000000010', 'ca9a0012-0000-0000-0000-000000000012', 'MA', 'a2222222-aaaa-aaaa-aaaa-aaaaaaaaaaaa', 'workshop', 'Casablanca Leather Workshop', 'Learn traditional Moroccan leatherworking — stamping, dyeing and stitching — in the medina.', ARRAY['en','fr','es','ary-Latn'], 12, 1, '{}', 1, 4, 120, 1, 'active', 'https://images.pexels.com/photos/21326994/pexels-photo-21326994.jpeg?auto=compress&cs=tinysrgb&h=650&w=940'),
